/* -------------------------------------------------------------------------------------------------
 * Caret placement
 * -----------------------------------------------------------------------------------------------*/

interface CaretRect {
  top: number
  bottom: number
  left: number
  right: number
}

/** Returns the caret rect in viewport coordinates, or null when it is not on screen. */
type CaretAnchor = () => CaretRect | null

type MenuSide = "top" | "bottom"

/* -------------------------------------------------------------------------------------------------
 * Suggestion popup parts, shared by MentionMenu and SlashMenu
 *
 * Focus never leaves the editor. The editor forwards keys through `menuRef.onKeyDown`, the popup
 * tracks the active row and reports its id for `aria-activedescendant`. Rows are found in the DOM,
 * so any markup composed from these parts navigates correctly.
 *
 * Motion: none. The menu opens from typing and is used all day, so it appears and updates
 * instantly, and the active row moves without a transition.
 * -----------------------------------------------------------------------------------------------*/

export interface MentionMenuHandle {
  /**
   * Arrow keys (and Ctrl+N, Ctrl+P) move, Enter and Tab pick, Escape closes. Returns true when
   * the key was used, so the caller can `preventDefault`.
   */
  onKeyDown: (event: KeyboardEvent | React.KeyboardEvent) => boolean
}

interface MentionMenuPopupProps extends Omit<React.ComponentProps<"div">, "children"> {
  open: boolean
  onOpenChange?: (open: boolean) => void
  /** Caret rect getter. Without one the popup renders in place, for docs and custom layouts. */
  anchor?: CaretAnchor | null
  /** Preferred side of the caret. `auto` picks the side with room and keeps it while open. */
  side?: MenuSide | "auto"
  /** Default 320. */
  width?: number
  /** Default 320. */
  maxHeight?: number
  menuRef?: React.Ref<MentionMenuHandle>
  /** Called with the active option's DOM id, for `aria-activedescendant` on the editor. */
  onActiveChange?: (id: string | undefined) => void
  /** Accessible name of the listbox. */
  label: string
  /** Change it when the query changes: the first row becomes active again. */
  resetKey?: string
  /** Shown under the list in a polite live region: empty and loading states. */
  status?: React.ReactNode
  /** Shown under everything: usage for the active row, a hint. */
  footer?: React.ReactNode
  /** Portal container. Default `document.body`. */
  container?: HTMLElement | null
  /** Listbox id. Generated by default. */
  listId?: string
  /** Text direction at the caret, so the popup lines up with the trigger. Default: the document's. */
  dir?: "ltr" | "rtl"
  children?: React.ReactNode
}

export interface SlashCommand {
  /** Without the slash: `review`, `test`, `compact`. */
  name: string
  description: string
  /** Group heading, for example "Session", "Code", "Skills". */
  category?: string
  /** Ghost text shown after the command is inserted: `<pr-number> [--strict]`. */
  argumentHint?: string
  /** Shortcut keys shown as `Kbd`, for example `["⌘", "K"]`. Decorative. */
  shortcut?: string[]
  /** `skill` rows read as reusable instructions rather than built-in commands. */
  kind?: "command" | "skill"
  /** Expands into this text instead of a chip. `{{name}}` becomes a variable to fill. */
  template?: string
  /** Runs right away (for example `/clear`) instead of being inserted. */
  immediate?: boolean
  keywords?: string[]
  icon?: React.ReactNode
  disabled?: boolean
  disabledReason?: string
}

/* -------------------------------------------------------------------------------------------------
 * SlashMenu
 * -----------------------------------------------------------------------------------------------*/

export interface SlashMenuProps
  extends Omit<
    MentionMenuPopupProps,
    "children" | "label" | "resetKey" | "status" | "footer" | "onSelect"
  > {
  commands: SlashCommand[]
  /** Text typed after the `/`. */
  query: string
  onSelect: (command: SlashCommand) => void
  /** Command names used recently, most recent first. Shown first while the query is empty. */
  recent?: string[]
  /** Most rows. Default 50. */
  limit?: number
  /** Second line of the empty state. */
  emptyHint?: React.ReactNode
  /** Shows the active command's arguments under the list. Default true. */
  showUsage?: boolean
  /** Accessible name. Default "Commands". */
  label?: string
}

interface RankOptions {
  /** Ids (mentions) or names (commands) used recently, most recent first. Shown first while the query is empty. */
  recent?: string[]
  /** Most rows to show. Default 50. */
  limit?: number
  /** Heading for the recent group. Default "Recent". */
  recentLabel?: string
  /** Order of the groups while the query is empty. Default: first appearance. */
  groupOrder?: string[]
}

/* -------------------------------------------------------------------------------------------------
 * Ranking and grouping
 * -----------------------------------------------------------------------------------------------*/

interface RankedItem<T> {
  item: T
  score: number
  /** Matched indices in `label` (mentions) or `name` (commands). */
  labelIndices: number[]
  /** Matched indices in `detail` when the label itself did not match. */
  detailIndices: number[]
}

interface RankedGroup<T> {
  key: string
  label: string
  items: RankedItem<T>[]
}

/* -------------------------------------------------------------------------------------------------
 * Fuzzy matching
 *
 * Case-insensitive subsequence match. Contiguous runs and word starts (after / . - _ space, or a
 * camelCase hump) score higher, gaps and long targets lower. Returns the matched indices so the
 * row can emphasize exactly the characters that matched.
 * -----------------------------------------------------------------------------------------------*/

interface FuzzyMatch {
  score: number
  indices: number[]
}

function isBoundary(text: string, i: number) {
  if (i === 0) return true
  const prev = text[i - 1] ?? ""
  const char = text[i] ?? ""
  if (/[\s/\\._\-:#@]/.test(prev)) return true
  return char !== char.toLowerCase() && prev === prev.toLowerCase()
}

function scan(q: string, t: string, text: string, preferBoundary: boolean): FuzzyMatch | null {
  const indices: number[] = []
  let score = 0
  let from = 0
  for (let k = 0; k < q.length; k++) {
    const char = q[k] as string
    const prev = indices[indices.length - 1]
    let pick = -1
    for (let i = from; i < t.length; i++) {
      if (t[i] !== char) continue
      if (pick === -1) pick = i
      // Stay contiguous when the previous character matched right before this one.
      if (!preferBoundary || i === (prev ?? -2) + 1) break
      if (isBoundary(text, i)) {
        pick = i
        break
      }
    }
    if (pick === -1) return null
    score += 10
    if (prev !== undefined && pick === prev + 1) score += 14
    if (isBoundary(text, pick)) score += 12
    if (prev !== undefined) score -= Math.min(pick - prev - 1, 12)
    indices.push(pick)
    from = pick + 1
  }
  return { score: score - t.length * 0.2, indices }
}

function fuzzyMatch(query: string, text: string): FuzzyMatch | null {
  if (!query) return { score: 0, indices: [] }
  const q = query.toLowerCase()
  const t = text.toLowerCase()
  if (q.length > t.length) return null

  // A contiguous hit beats any scattered one; prefer it when it exists.
  const at = t.indexOf(q)
  if (at !== -1) {
    const indices = Array.from({ length: q.length }, (_, k) => at + k)
    const score =
      100 + q.length * 12 + (at === 0 ? 40 : isBoundary(text, at) ? 24 : 0) - at - t.length * 0.2
    return { score, indices }
  }

  // Word starts first ("rt" picks the t of ".ts" in "runs.ts"), plain leftmost as the fallback
  // when jumping ahead would leave later characters without a match.
  return scan(q, t, text, true) ?? scan(q, t, text, false)
}

function isContiguous(indices: number[]) {
  return (
    indices.length > 0 &&
    (indices[indices.length - 1] as number) - (indices[0] as number) === indices.length - 1
  )
}

function rankFields(query: string, primary: string, secondary: (string | undefined)[]) {
  const main = fuzzyMatch(query, primary)
  // A scattered label hit must earn about 10 points per character ("rnts" in runs.ts does,
  // "no" in pagination.ts does not).
  let best: { score: number; field: number; indices: number[] } | null =
    main && main.score >= query.length * 10
      ? { score: main.score + 30, field: -1, indices: main.indices }
      : null
  secondary.forEach((value, field) => {
    if (!value) return
    const m = fuzzyMatch(query, value)
    // Secondary text is long and noisy: only contiguous hits count.
    if (!m || !isContiguous(m.indices)) return
    if (!best || m.score * 0.7 > best.score)
      best = { score: m.score * 0.7, field, indices: m.indices }
  })
  return best as { score: number; field: number; indices: number[] } | null
}

function groupRanked<T>(
  ranked: (RankedItem<T> & { group: string; key: string })[],
  query: string,
  options: RankOptions,
): RankedGroup<T>[] {
  const { recent = [], limit = 50, recentLabel = "Recent", groupOrder } = options
  const groups = new Map<string, RankedGroup<T>>()
  const add = (key: string, label: string, entry: RankedItem<T>) => {
    let group = groups.get(key)
    if (!group) {
      group = { key, label, items: [] }
      groups.set(key, group)
    }
    group.items.push(entry)
  }

  if (!query) {
    const recentSet = new Set(recent)
    const recents = recent
      .map((id) => ranked.find((r) => r.key === id))
      .filter((r): r is NonNullable<typeof r> => Boolean(r))
    for (const r of recents) add("__recent", recentLabel, r)
    const rest = ranked.filter((r) => !recentSet.has(r.key))
    const order = groupOrder ?? []
    const sorted = [...rest].sort((a, b) => {
      const ia = order.indexOf(a.group)
      const ib = order.indexOf(b.group)
      return (ia === -1 ? order.length : ia) - (ib === -1 ? order.length : ib)
    })
    for (const r of sorted) add(r.group, r.group, r)
  } else {
    // Groups ordered by their best hit, rows by score.
    const sorted = [...ranked].sort((a, b) => b.score - a.score)
    for (const r of sorted) add(r.group, r.group, r)
  }

  let left = limit
  const out: RankedGroup<T>[] = []
  for (const group of groups.values()) {
    if (left <= 0) break
    const items = group.items.slice(0, left)
    left -= items.length
    out.push({ ...group, items })
  }
  return out
}

/** Filters, ranks and groups slash commands for a query. */
function rankCommands(
  commands: SlashCommand[],
  query: string,
  options: RankOptions = {},
): RankedGroup<SlashCommand>[] {
  const ranked: (RankedItem<SlashCommand> & { group: string; key: string })[] = []
  for (const item of commands) {
    const group = item.category ?? (item.kind === "skill" ? "Skills" : "Commands")
    if (!query) {
      ranked.push({ item, score: 0, labelIndices: [], detailIndices: [], group, key: item.name })
      continue
    }
    const best = rankFields(query, item.name, [item.description, ...(item.keywords ?? [])])
    if (!best) continue
    // Description hits are useful but noisy; only keep strong ones.
    if (best.field !== -1 && best.score < 60) continue
    ranked.push({
      item,
      score: best.score,
      labelIndices: best.field === -1 ? best.indices : [],
      detailIndices: best.field === 0 ? best.indices : [],
      group,
      key: item.name,
    })
  }
  return groupRanked(ranked, query, options)
}

/* -------------------------------------------------------------------------------------------------
 * Usage line
 * -----------------------------------------------------------------------------------------------*/

function variableCount(template: string) {
  return new Set(Array.from(template.matchAll(/\{\{\s*([^{}]+?)\s*\}\}/g), (m) => m[1])).size
}

function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        "rounded-(--chatcn-radius-xs) bg-(color:--chatcn-fill) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) inline-flex h-5 min-w-5 items-center justify-center px-1 font-sans tabular-nums shadow-[inset_0_-1px_0_var(--chatcn-alpha-300)]",
        className,
      )}
      {...props}
    />
  )
}

/** What the footer says about the active command: its arguments, or what a template does. */
function usage(command: SlashCommand | undefined) {
  if (!command) return null
  if (command.template) {
    const n = variableCount(command.template)
    return (
      <span>
        Inserts a prompt
        {n ? (
          <>
            {" "}
            with {n} {n === 1 ? "variable" : "variables"}. <Kbd>Tab</Kbd> moves between them.
          </>
        ) : (
          "."
        )}
      </span>
    )
  }
  if (command.immediate) return <span>Runs right away.</span>
  if (command.argumentHint) {
    return (
      <span className="flex min-w-0 items-baseline gap-1.5 font-mono">
        <span className="text-(color:--chatcn-fg-muted) shrink-0">/{command.name}</span>
        <span className="truncate">{command.argumentHint}</span>
      </span>
    )
  }
  return null
}

function optionId(listId: string, value: string) {
  return `${listId}-${value.replace(/[^\w-]/g, "_")}`
}

interface MenuPlacement {
  side: MenuSide
  style: React.CSSProperties
}

/**
 * Places a menu next to the caret with fixed positioning. The side is picked once by the caller
 * (pass `lockedSide` to keep it while the list shrinks), the start edge follows the caret and stays
 * inside the viewport.
 */
function placeMenu(
  rect: CaretRect,
  {
    width,
    maxHeight,
    side = "auto",
    lockedSide,
    gap = 6,
    margin = 8,
    dir = "ltr",
  }: {
    width: number
    maxHeight: number
    side?: MenuSide | "auto"
    lockedSide?: MenuSide
    gap?: number
    margin?: number
    dir?: "ltr" | "rtl"
  },
): MenuPlacement {
  const vw = window.innerWidth
  const vh = window.innerHeight
  const below = vh - rect.bottom - gap - margin
  const above = rect.top - gap - margin
  const chosen: MenuSide =
    lockedSide ??
    (side !== "auto"
      ? side === "bottom" && below < 160 && above > below
        ? "top"
        : side === "top" && above < 160 && below > above
          ? "bottom"
          : side
      : below >= Math.min(maxHeight, 240) || below >= above
        ? "bottom"
        : "top")
  const w = Math.min(width, vw - margin * 2)
  const style: React.CSSProperties = {
    position: "fixed",
    width: w,
    maxHeight: Math.max(120, Math.min(maxHeight, chosen === "bottom" ? below : above)),
  }
  // Line the popup up a little before the trigger character, inside the viewport.
  if (dir === "rtl") {
    style.right = Math.min(Math.max(margin, vw - rect.right - 8), vw - w - margin)
  } else {
    style.left = Math.min(Math.max(margin, rect.left - 8), vw - w - margin)
  }
  if (chosen === "bottom") style.top = rect.bottom + gap
  else style.bottom = vh - rect.top + gap
  return { side: chosen, style }
}

/** Surface shared by popovers and menus: 12 px radius, surface fill, medium shadow. */
const popupSurface = cn(
  "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-md) rounded-(--chatcn-radius-lg) outline-none",
  "max-h-(--available-height) max-w-(--available-width)",
  // Shadows vanish in forced colors; keep an edge.
  "forced-colors:outline-1 forced-colors:outline-solid",
)

interface PopupContextValue {
  listId: string
  active: string | undefined
  setActive: (value: string) => void
}

const PopupContext = React.createContext<PopupContextValue | null>(null)

/** The floating listbox, anchored to the caret. Holds the active row and the keyboard handle. */
function MentionMenuPopup({
  open,
  onOpenChange,
  anchor,
  side = "auto",
  width = 320,
  maxHeight = 320,
  menuRef,
  onActiveChange,
  label,
  resetKey,
  status,
  footer,
  container,
  listId: listIdProp,
  dir: dirProp,
  className,
  style,
  children,
  ...props
}: MentionMenuPopupProps) {
  const generated = React.useId()
  const listId = listIdProp ?? `chatcn-menu-${generated.replace(/:/g, "")}`
  const listRef = React.useRef<HTMLDivElement>(null)
  const [active, setActiveState] = React.useState<string>()
  const activeRef = React.useRef(active)
  activeRef.current = active

  const options = React.useCallback(
    () =>
      Array.from(
        listRef.current?.querySelectorAll<HTMLElement>(
          '[role="option"]:not([aria-disabled="true"])',
        ) ?? [],
      ),
    [],
  )

  const setActive = React.useCallback((value: string) => setActiveState(value), [])

  // Keep the active row valid: first row on open and on every new query, and whenever the
  // active row disappears from the results.
  const lastReset = React.useRef<string | undefined>(undefined)
  React.useLayoutEffect(() => {
    if (!open) {
      lastReset.current = undefined
      return
    }
    const rows = options()
    const values = rows.map((row) => row.dataset.value as string)
    const reset = lastReset.current !== (resetKey ?? "")
    lastReset.current = resetKey ?? ""
    if (reset || !active || !values.includes(active)) {
      const next = values[0]
      if (next !== active) setActiveState(next)
      if (reset && listRef.current) listRef.current.scrollTop = 0
    }
  })

  const activeId = open && active ? optionId(listId, active) : undefined
  const onActiveChangeRef = React.useRef(onActiveChange)
  onActiveChangeRef.current = onActiveChange
  React.useEffect(() => {
    onActiveChangeRef.current?.(activeId)
  }, [activeId])
  React.useEffect(() => () => onActiveChangeRef.current?.(undefined), [])

  // One key handler for both routes: the editor forwards its keys through `menuRef`, and the list
  // handles them itself when it has focus (Tab into a menu shown without an editor).
  const onKey = React.useCallback(
    (event: KeyboardEvent | React.KeyboardEvent) => {
      if (!open) return false
      const key = event.key
      const ctrl = event.ctrlKey && !event.metaKey && !event.altKey
      const down = key === "ArrowDown" || (ctrl && key === "n")
      const up = key === "ArrowUp" || (ctrl && key === "p")
      if (down || up) {
        const rows = options()
        if (rows.length === 0) return true
        const values = rows.map((row) => row.dataset.value as string)
        const at = activeRef.current ? values.indexOf(activeRef.current) : -1
        const next = down ? (at + 1) % values.length : (at - 1 + values.length) % values.length
        setActiveState(values[next])
        rows[next]?.scrollIntoView({ block: "nearest" })
        return true
      }
      if ((key === "Enter" || key === "Tab") && !event.shiftKey) {
        const row = options().find((r) => r.dataset.value === activeRef.current)
        if (!row) return false
        row.click()
        return true
      }
      if (key === "Escape") {
        onOpenChange?.(false)
        return true
      }
      return false
    },
    [open, onOpenChange, options],
  )
  React.useImperativeHandle(menuRef, () => ({ onKeyDown: onKey }), [onKey])

  // Fixed placement next to the caret. The side is chosen once per opening so the list never
  // jumps across the caret while results shrink.
  const lockedSide = React.useRef<MenuSide | undefined>(undefined)
  const [placement, setPlacement] = React.useState<{ side: MenuSide; style: React.CSSProperties }>()
  const [, force] = React.useReducer((n: number) => n + 1, 0)
  React.useLayoutEffect(() => {
    if (!open || !anchor) {
      lockedSide.current = undefined
      setPlacement(undefined)
      return
    }
    const rect = anchor()
    if (!rect) return
    const dir = dirProp ?? (document.documentElement.dir === "rtl" ? "rtl" : "ltr")
    const next = placeMenu(rect, { width, maxHeight, side, lockedSide: lockedSide.current, dir })
    lockedSide.current = next.side
    setPlacement((prev) => (prev && JSON.stringify(prev) === JSON.stringify(next) ? prev : next))
  })
  const floating = Boolean(anchor)
  React.useEffect(() => {
    if (!open || !floating) return
    window.addEventListener("resize", force)
    window.addEventListener("scroll", force, true)
    return () => {
      window.removeEventListener("resize", force)
      window.removeEventListener("scroll", force, true)
    }
  }, [open, floating])

  // Fade only the edges that hide rows. Rows change with every keystroke, so measure each render;
  // the state bails out unless an edge flips.
  const [fade, setFade] = React.useState({ top: false, bottom: false })
  const measureFade = React.useCallback(() => {
    const el = listRef.current
    if (!el) return
    const top = el.scrollTop > 1
    const bottom = el.scrollHeight - el.clientHeight - el.scrollTop > 1
    setFade((prev) => (prev.top === top && prev.bottom === bottom ? prev : { top, bottom }))
  }, [])
  React.useLayoutEffect(measureFade)

  if (!open) return null

  const popup = (
    <div
      data-slot="mention-menu"
      data-side={placement?.side}
      className={cn(
        popupSurface,
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] flex flex-col overflow-hidden",
        floating ? "z-50" : "relative",
        floating && !placement && "invisible",
        className,
      )}
      style={
        floating
          ? { ...placement?.style, ...style }
          : { width, maxWidth: "100%", maxHeight, ...style }
      }
      {...props}
    >
      <PopupContext.Provider value={{ listId, active, setActive }}>
        <div
          ref={listRef}
          id={listId}
          role="listbox"
          aria-label={label}
          aria-activedescendant={activeId}
          // The field drives the list with aria-activedescendant while it has focus. The list is
          // in the tab order too, so its scroll is reachable without a field (a menu shown in
          // place) and it answers the same keys. A press on it never takes focus from the field.
          tabIndex={0}
          onKeyDown={(event) => {
            // Tab picks from the editor, but on the list itself it moves focus on as usual.
            if (event.key !== "Tab" && onKey(event)) event.preventDefault()
          }}
          onMouseDown={(event) => event.preventDefault()}
          onScroll={measureFade}
          data-fade-top={fade.top ? "" : undefined}
          data-fade-bottom={fade.bottom ? "" : undefined}
          className={cn(
            "chatcn-scroll chatcn-focus min-h-0 flex-1 overflow-y-auto overscroll-contain p-1 -outline-offset-2 empty:hidden",
            // The row cut by an edge fades out instead of ending mid-glyph.
            "data-[fade-bottom]:[--chatcn-fade-bottom:24px] data-[fade-top]:[--chatcn-fade-top:24px]",
            "[mask-image:linear-gradient(to_bottom,transparent,#000_var(--chatcn-fade-top,0px),#000_calc(100%-var(--chatcn-fade-bottom,0px)),transparent)]",
          )}
        >
          {children}
        </div>
      </PopupContext.Provider>
      {status ? (
        <div role="status" aria-live="polite" className="p-1 [[role=listbox]:not(:empty)+&]:pt-0">
          {status}
        </div>
      ) : null}
      {footer ? (
        <div
          data-slot="mention-menu-footer"
          className="border-(color:--chatcn-border) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) border-t px-3 py-2"
        >
          {footer}
        </div>
      ) : null}
    </div>
  )

  if (!floating) return popup
  if (typeof document === "undefined") return null
  return createPortal(popup, container ?? document.body)
}

/** The no-results state. Say what was searched and what to try. */
function MentionMenuEmpty({
  query,
  hint,
  className,
  children,
}: {
  query?: string
  hint?: React.ReactNode
  className?: string
  children?: React.ReactNode
}) {
  return (
    <div className={cn("flex flex-col gap-0.5 px-2 py-2.5", className)}>
      <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg)">
        {children ?? (query ? <>No matches for “{query}”</> : "No matches")}
      </p>
      {hint ? <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) text-pretty">{hint}</p> : null}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Group, item, highlight, states
 * -----------------------------------------------------------------------------------------------*/

interface MentionMenuGroupProps extends React.ComponentProps<"div"> {
  /** Sentence case heading: "Files", "Recent". */
  heading: React.ReactNode
}

function MentionMenuGroup({ heading, className, children, ...props }: MentionMenuGroupProps) {
  const id = React.useId()
  return (
    // biome-ignore lint/a11y/useSemanticElements: a listbox group, not a form fieldset
    <div
      role="group"
      aria-labelledby={id}
      data-slot="mention-menu-group"
      className={cn("not-first:mt-1", className)}
      {...props}
    >
      <div
        id={id}
        className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-7 items-center px-2 font-medium select-none"
      >
        {heading}
      </div>
      {children}
    </div>
  )
}

interface MentionMenuItemProps extends Omit<React.ComponentProps<"div">, "onSelect"> {
  /** Unique within the menu. */
  value: string
  disabled?: boolean
  onSelect?: () => void
}

function usePopup(part: string) {
  const context = React.useContext(PopupContext)
  if (!context) throw new Error(`${part} must be inside <MentionMenuPopup>.`)
  return context
}

/**
 * One option row. Pointer movement makes it active, a click picks it, and pressing never takes
 * focus from the editor.
 */
function MentionMenuItem({
  value,
  disabled = false,
  onSelect,
  className,
  children,
  ...props
}: MentionMenuItemProps) {
  const { listId, active, setActive } = usePopup("MentionMenuItem")
  const isActive = active === value
  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: keys arrive from the editor through menuRef
    // biome-ignore lint/a11y/useFocusableInteractive: focus stays in the editor (aria-activedescendant)
    <div
      id={optionId(listId, value)}
      role="option"
      aria-selected={isActive}
      aria-disabled={disabled || undefined}
      data-slot="mention-menu-item"
      data-value={value}
      data-active={isActive ? "" : undefined}
      onMouseDown={(event) => event.preventDefault()}
      onPointerMove={() => {
        if (!disabled && !isActive) setActive(value)
      }}
      onClick={() => {
        if (!disabled) onSelect?.()
      }}
      className={cn(
        "group/mention-item rounded-(--chatcn-radius-md) relative flex min-h-8 cursor-default items-center gap-2 px-2 py-1.5 select-none",
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) text-start outline-none",
        "data-[active]:bg-(color:--chatcn-fill-hover)",
        // Disabled rows step the label back a shade instead of fading, so the reason stays readable.
        "aria-disabled:text-(color:--chatcn-fg-subtle) aria-disabled:cursor-not-allowed",
        "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        "pointer-coarse:min-h-11",
        "forced-colors:data-[active]:outline-1 forced-colors:data-[active]:outline-solid",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  )
}

/** Splits text into matched and unmatched runs for rendering. */
function highlightSegments(text: string, indices: number[]) {
  const set = new Set(indices)
  const segments: { text: string; match: boolean }[] = []
  for (let i = 0; i < text.length; i++) {
    const match = set.has(i)
    const last = segments[segments.length - 1]
    if (last && last.match === match) last.text += text[i]
    else segments.push({ text: text[i] as string, match })
  }
  return segments
}

/** Text with the matched characters emphasized. Unmatched characters step back one shade. */
function MentionMenuHighlight({
  text,
  indices,
  className,
}: {
  text: string
  indices: number[]
  className?: string
}) {
  if (indices.length === 0) return <span className={cn("truncate", className)}>{text}</span>
  return (
    <span className={cn("text-(color:--chatcn-fg-muted) truncate", className)}>
      {highlightSegments(text, indices).map((segment, i) =>
        segment.match ? (
          <mark key={i} className="text-(color:--chatcn-fg) bg-transparent font-medium">
            {segment.text}
          </mark>
        ) : (
          <React.Fragment key={i}>{segment.text}</React.Fragment>
        ),
      )}
    </span>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"M7 10.5h10a3 3 0 0 1 3 3V18a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3v-4.5a3 3 0 0 1 3-3"}],
  ["path", {"d":"M8 7.5V7a4 4 0 0 1 4-4 4 4 0 0 1 4 4v.5"}],
]

const LockIcon: Icon = /* @__PURE__ */ createIcon("lock", iconNode)

/**
 * The `/` popup: commands and skills grouped by category, with descriptions, shortcuts and the
 * active command's arguments. Built from the MentionMenu parts, so keys work the same way.
 */
export function SlashMenu({
  commands,
  query,
  onSelect,
  recent,
  limit,
  emptyHint = "Commands start with a letter. Press Esc to type a plain slash.",
  showUsage = true,
  label = "Commands",
  width = 400,
  onActiveChange,
  ...props
}: SlashMenuProps) {
  const groups = React.useMemo(
    () => rankCommands(commands, query, { recent, limit }),
    [commands, query, recent, limit],
  )
  // When some commands carry an icon, the rest keep an empty slot so every name starts on the
  // same edge instead of jumping left and right down the list.
  const anyIcon = groups.some((group) => group.items.some(({ item }) => item.icon))
  const [activeName, setActiveName] = React.useState<string>()
  const active = commands.find((c) => c.name === activeName)
  const footer = showUsage ? usage(active) : null

  return (
    <MentionMenuPopup
      label={label}
      resetKey={query}
      width={width}
      status={
        groups.length === 0 ? <MentionMenuEmpty query={`/${query}`} hint={emptyHint} /> : null
      }
      footer={footer}
      onActiveChange={(id) => {
        onActiveChange?.(id)
        const row = id ? document.getElementById(id) : null
        setActiveName(row?.dataset.value)
      }}
      {...props}
    >
      {groups.map((group) => (
        <MentionMenuGroup key={group.key} heading={group.label}>
          {group.items.map(({ item, labelIndices, detailIndices }) => (
            <MentionMenuItem
              key={item.name}
              value={item.name}
              disabled={item.disabled}
              onSelect={() => onSelect(item)}
            >
              {item.icon ? (
                <span
                  aria-hidden="true"
                  className="text-(color:--chatcn-fg-subtle) group-data-[active]/mention-item:text-(color:--chatcn-fg) grid shrink-0 place-items-center"
                >
                  {item.icon}
                </span>
              ) : anyIcon ? (
                <span aria-hidden="true" className="size-4 shrink-0" />
              ) : null}
              <span className="flex min-w-0 shrink-0 items-baseline font-medium">
                <span aria-hidden="true" className="text-(color:--chatcn-fg-subtle)">
                  /
                </span>
                <MentionMenuHighlight text={item.name} indices={labelIndices} />
              </span>
              {item.disabled && item.disabledReason ? (
                <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center gap-1">
                  <LockIcon className="size-3.5!" />
                  <span className="truncate">{item.disabledReason}</span>
                </span>
              ) : (
                <MentionMenuHighlight
                  text={item.description}
                  indices={detailIndices}
                  className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) min-w-0 flex-1"
                />
              )}
              {item.shortcut?.length ? (
                <span aria-hidden="true" className="ms-auto flex shrink-0 gap-0.5 ps-2">
                  {item.shortcut.map((key) => (
                    <Kbd key={key}>{key}</Kbd>
                  ))}
                </span>
              ) : null}
            </MentionMenuItem>
          ))}
        </MentionMenuGroup>
      ))}
    </MentionMenuPopup>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Argument hint
 * -----------------------------------------------------------------------------------------------*/

/**
 * Ghost text after an inserted command, the way a terminal shows usage: `<pr-number> [--strict]`.
 * Decorative and click-through; it disappears as soon as an argument is typed.
 */
export function SlashArgumentHint({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="slash-argument-hint"
      aria-hidden="true"
      className={cn(
        "text-(color:--chatcn-fg-subtle) pointer-events-none font-mono whitespace-pre select-none",
        className,
      )}
      {...props}
    />
  )
}

export default SlashMenu

